{"implementation":"import math


def solve(case):
    def is_number(value):
        return isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value)

    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "threshold" not in case or "calls" not in case:
        raise ValueError("missing required case field")
    if not is_number(case["threshold"]):
        raise ValueError("threshold must be a finite number")
    if not isinstance(case["calls"], list):
        raise ValueError("calls must be a list")

    validated = []
    seen_ids = set()
    for call in case["calls"]:
        if not isinstance(call, dict):
            raise ValueError("each call must be an object")
        required = ("call_id", "loss_without_call", "loss_with_call", "prediction_tokens", "parseable")
        if any(field not in call for field in required):
            raise ValueError("missing required call field")
        call_id = call["call_id"]
        if not isinstance(call_id, str):
            raise ValueError("call_id must be a string")
        if call_id in seen_ids:
            raise ValueError("call_id values must be unique")
        seen_ids.add(call_id)
        if not is_number(call["loss_without_call"]) or not is_number(call["loss_with_call"]):
            raise ValueError("losses must be finite numbers")
        tokens = call["prediction_tokens"]
        if not isinstance(tokens, int) or isinstance(tokens, bool) or tokens < 0:
            raise ValueError("prediction_tokens must be a nonnegative integer")
        if not isinstance(call["parseable"], bool):
            raise ValueError("parseable must be boolean")
        validated.append((call_id, call["loss_without_call"], call["loss_with_call"], tokens, call["parseable"]))

    accepted_call_ids = []
    diagnostics = []
    threshold = case["threshold"]
    for call_id, loss_without, loss_with, tokens, parseable in validated:
        normalized_gain = (loss_without - loss_with) / max(tokens, 1)
        normalized_gain = round(normalized_gain, 6)
        accepted = parseable and normalized_gain >= threshold
        diagnostics.append({
            "accepted": accepted,
            "call_id": call_id,
            "normalized_gain": normalized_gain,
        })
        if accepted:
            accepted_call_ids.append(call_id)

    return {
        "accepted_call_ids": accepted_call_ids,
        "diagnostics": diagnostics,
    }
